-- ============================================================
-- Import des données réelles : sets Euro par pays
-- Source : https://monnaies-euros.com/euros.php (parsé directement, pas de reconstruction manuelle)
-- Flags non incluses (à sourcer séparément) : flag_url laissé vide
-- ============================================================

-- 1) Pays
on conflict (slug) do nothing;

-- 2) Séries par pays

-- 3) Pièces (une ligne par série x valeur) — URLs copiées telles quelles depuis la source
on conflict (series_id, value) do update set image_url = excluded.image_url;
